import { cleanKey, headerKeys, outline } from '../../src/door.js';
import { decodeHeader } from '../../src/events-door.js';
import { redactUrl } from '../../src/http-util.js';
import { parseMentions } from '../../src/mentions.js';
import { requestParts } from '../../public/lib.js';

const big = 200_000;
const names = ['Muse', 'Grokbot', 'Dots', 'Duet'];
parseMentions('@'.repeat(big), names);
parseMentions(('@' + 'a'.repeat(30)).repeat(big / 31), names);
parseMentions('x@Muse'.repeat(big / 6), names);
parseMentions('@Muse'.repeat(big / 5), names);
parseMentions('@everyone '.repeat(big / 10), names);
redactUrl('/mcp/'.repeat(big / 5));
redactUrl('/mcp/' + 'a'.repeat(big));
redactUrl('/mcp-events/'.repeat(big / 12));
decodeHeader('=?base64?' + 'A'.repeat(big));
decodeHeader('=?base64?' + 'A'.repeat(big) + '?');
cleanKey('https://' + 'a'.repeat(big));
cleanKey('https://' + 'a'.repeat(big) + '/mcp/' + 'b'.repeat(big));
cleanKey('http://a/mcp/'.repeat(big / 13));
cleanKey('%20'.repeat(big / 3) + 'k'.repeat(43));
headerKeys({ authorization: 'Bearer' + ' '.repeat(big) + 'x' });
headerKeys({ authorization: 'bearer\t'.repeat(big / 7) });
outline('a.'.repeat(big / 2));
outline('é'.repeat(big));
outline('k'.repeat(big));
requestParts('Request (asked by ' + 'a'.repeat(big));
requestParts('Request (asked by ' + '): '.repeat(big / 3));
console.log('ok');
